"""Regenerates src/main/kotlin/.../MusicData.kt from music/*.ogg.

Same as embed_sounds.py, for the longer tracks the Nyan party plays through MediaPlayer (SoundPool is
for short clips). The Nyan Cat song (daniwell) comes from iliana/html5nyancat: copyrighted, so this
plugin stays local-only.

Run from the plugin folder:  python tools/embed_music.py
"""
import base64
import pathlib

HERE = pathlib.Path(__file__).resolve().parent.parent
OUT = HERE / "src/main/kotlin/com/bleelblep/sparkle/MusicData.kt"
CHUNK = 60000

lines = [
    "// GENERATED by tools/embed_music.py from music/*.ogg -- do not edit by hand.",
    "// The Nyan Cat song (daniwell), via iliana/html5nyancat. Copyrighted: local use only.",
    "",
    "package com.bleelblep.sparkle",
    "",
    "internal object MusicData {",
    "\t/** File name -> base64 chunks, joined in order. */",
    "\tval files: Map<String, Array<String>> = mapOf(",
]
for path in sorted((HERE / "music").glob("*.ogg")):
    data = base64.b64encode(path.read_bytes()).decode("ascii")
    chunks = [data[i : i + CHUNK] for i in range(0, len(data), CHUNK)]
    body = ", ".join(f'"{c}"' for c in chunks)
    lines.append(f'\t\t"{path.name}" to arrayOf({body}),')
lines += ["\t)", "}", ""]
OUT.write_text("\n".join(lines), encoding="utf-8")
print(f"wrote {OUT.name}: {OUT.stat().st_size} bytes")
